// Generated by `npm run toolkits:sync` in the CMS repository (toolkits/client). Do not edit here.
// Shapes the Astral delivery API returns (cms/docs/API.md). Fields of an entry
// are typed loosely on purpose: each site narrows them with its own interfaces.

export type RenderMode = "static" | "revalidate" | "dynamic";

/** How the project places the locale in public URLs (Configurações › Idiomas). */
export type LocaleUrlMode = "prefix" | "prefix-all" | "domain" | "none";

export type LocaleFormat = {
  locales: string[];
  defaultLocale: string;
  mode: LocaleUrlMode;
  /** Base URL per locale, used only by the `domain` mode (no trailing slash). */
  domains: Record<string, string>;
};

export type Media = {
  id: string;
  /** The optimized WebP when it exists, else the file as uploaded. */
  url: string;
  original: string;
  mime: string;
  size: number;
  filename: string;
  alt: string;
  caption: string | null;
  width?: number | null;
  height?: number | null;
  focal?: { x: number | null; y: number | null };
  dominantColor?: string | null;
  /** A tiny inline WebP (data URI) to paint before the image arrives. */
  placeholder?: string | null;
  /** WebP candidates at the CMS widths, ending at the file's own width. */
  srcset?: string;
  optimized?: { size: number; width: number; height: number; mime: string } | null;
  formats?: { webp: string; avif: string };
};

export type Term = {
  id: string;
  slug: string;
  name: string;
  description: string | null;
  parent: { id: string; slug: string } | null;
  url: string | null;
  depth?: number;
  count?: number;
  children?: Term[];
};

export type Seo = {
  title: string | null;
  description: string | null;
  image: Media | null;
  canonical: string | null;
  noindex: boolean;
};

export type EntryMeta = {
  url: string | null;
  publishedAt: string | null;
  updatedAt: string;
  status?: "draft" | "changed" | "published";
  alternates?: { locale: string; url: string | null }[];
  jsonLd?: Record<string, unknown>;
};

export type Entry<Fields extends Record<string, unknown> = Record<string, unknown>> = Fields & {
  id: string;
  type: string;
  locale: string;
  slug?: string;
  seo?: Seo;
  meta: EntryMeta;
};

/** A block of a `blocks` field: the component apiId plus its fields. */
export type Block<Fields extends Record<string, unknown> = Record<string, unknown>> = Fields & {
  component: string;
  key: string;
};

export type ListMeta = {
  page: number;
  pageSize: number;
  offset: number;
  total: number;
  pageCount: number;
  manualOrder?: boolean;
};

export type ListResult<T> = { data: T[]; meta: ListMeta };

export type MenuItem = {
  id: string;
  label: string;
  url: string | null;
  kind: "entry" | "term" | "archive" | "url";
  newTab: boolean;
  className: string;
  children: MenuItem[];
};

export type Menu = { apiId: string; name: string; items: MenuItem[] };

export type SchemaField = {
  apiId: string;
  type: string;
  label: string;
  required?: boolean;
  options: Record<string, unknown>;
};

export type SchemaType = {
  apiId: string;
  name: string;
  kind: "COLLECTION" | "SINGLE";
  seo: boolean;
  urlPattern: string | null;
  /** Missing on older servers: treated as "static" (see renderMode). */
  render?: RenderMode;
  fields: SchemaField[];
};

export type SchemaTaxonomy = {
  apiId: string;
  name: string;
  singularName: string | null;
  hierarchical: boolean;
  types: string[];
  urlPattern: string | null;
};

export type SchemaComponent = { apiId: string; name: string; fields: SchemaField[] };

export type Schema = {
  locales: string[];
  defaultLocale: string;
  /** Present once the server delivers the URL format; the client falls back to "prefix". */
  localeUrls?: LocaleUrlMode;
  localeDomains?: Record<string, string>;
  types: SchemaType[];
  taxonomies: SchemaTaxonomy[];
  components: SchemaComponent[];
};

export type SitemapUrl = {
  loc: string;
  url: string;
  kind: "entry" | "listing" | "term";
  type: string;
  id: string | null;
  locale: string;
  lastmod: string;
  alternates: { locale: string; url: string; loc: string }[];
  images: { loc: string; alt: string }[];
};

export type Sitemap = { data: SitemapUrl[]; meta: { siteUrl: string | null; total: number } };

export type Redirect = { from: string; to: string; status: number };

export type JsonLd = { "@context": string; "@graph": Record<string, unknown>[] };

export type Analytics = { provider: "ga4"; measurementId: string; consentDefault: string; events: Record<string, string> } | null;

export type FilterValue = string | number | boolean | Array<string | number>;
export type FilterOp = "eq" | "ne" | "gt" | "gte" | "lt" | "lte" | "in" | "contains" | "null";

/** `{ price: { lte: 50 }, category: "design", title: { contains: "x" } }` becomes `filter[price][lte]=50&filter[category]=design...` */
export type Filter = Record<string, FilterValue | Partial<Record<FilterOp, FilterValue>>>;

export type ListOptions = {
  locale?: string;
  filter?: Filter;
  /** `"date:desc,title"` or an array of the same parts; `"position"` for the manual order. */
  sort?: string | string[];
  page?: number;
  pageSize?: number;
  limit?: number;
  offset?: number;
  /** Top-level fields to return. */
  fields?: string[];
  /** Relation levels to populate (0 to 3; the API default is 1). */
  populate?: number;
  preview?: boolean;
  richtext?: "html" | "markdown";
};

export type GetOptions = Pick<ListOptions, "locale" | "populate" | "preview" | "richtext" | "fields">;

// ── Webhooks ──────────────────────────────────────────────────────────────

export type WebhookEventName =
  | "entry.created"
  | "entry.updated"
  | "entry.published"
  | "entry.unpublished"
  | "entry.deleted"
  | "asset.created"
  | "asset.updated"
  | "asset.deleted"
  | "schema.updated"
  | "taxonomy.updated"
  | "menu.updated"
  | "settings.updated"
  | "form.submitted"
  | "site.rebuild";

export type WebhookData = {
  type?: string;
  documentId?: string;
  locale?: string;
  /** Public paths of the entry in every affected locale (old and new slug). */
  paths?: string[];
  /** Cache tags: `type:<apiId>`, `entry:<id>`, `menus`, `settings`, `schema`, `taxonomy:<apiId>`, `asset:<id>`. */
  tags?: string[];
  [key: string]: unknown;
};

export type WebhookEvent = { event: WebhookEventName; projectId: string; sentAt: string; data: WebhookData };

export type WebhookBatch = {
  event: "batch";
  projectId: string;
  sentAt: string;
  count: number;
  from: string;
  to: string;
  events: { event: WebhookEventName; at: string; data: WebhookData }[];
};

export type WebhookPayload = WebhookEvent | WebhookBatch;
